parameters.text:
=You will be giving text that contains many separate prompts. I want you to extract these into an array of strings where each item in the array is one of the individual prompts. The prompts should remain exactly as they were provided.

---
{{ $json.candidates[0].content.parts[0].text }}

parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Extracted Prompts",
  "description": "A schema designed to hold a list of individual prompts that have been extracted from a larger body of text. Use this to format the extracted prompts.",
  "type": "object",
  "properties": {
    "prompts": {
      "type": "array",
      "description": "An array where each element is a single, distinct prompt string that was extracted from the user's input.",
      "items": {
        "type": "string",
        "description": "A single prompt statement."
      }
    }
  },
  "required": [
    "prompts"
  ]
}

parameters.jsonBody:
={
  "contents": [{
    "parts": [
      { "text": {{ JSON.stringify("Generate a photo-realistic image using the provided model image and the provided article of clothing. Here are the image details you need to follow:\n" + $json.prompts) }} },
      {
        "inline_data": {
          "mime_type": "image/png",
          "data": "{{ $node['convert_upload_to_base64'].json.data }}"
        }
      },
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": "{{ $node['set_model_result'].json.image_result }}"
        }
      }
    ]
  }]
}
